namespace {template<typename...T>std::string format(const char* pattern,T... values){char text[256];std::snprintf(text,sizeof(text),pattern,values...);return text;}u32 alpha(u32 color,u32 source){return (color&0xffffff)|(source&0xff000000);} }
std::string grouped_number(u32 value){if(value<1000)return format("%d",signed_bits(value));if(value<1000000)return format("%d,%.3d",value/1000,value%1000);if(value<1000000000)return format("%d,%.3d,%.3d",value/1000000,(value/1000)%1000,value%1000);return format("%d,%.3d,%.3d,%.3d",value/1000000000,(value/1000000)%1000,(value/1000)%1000,value%1000);}
std::string score_number(u32 value,i32 last_digit){if(value<100)return format("%d",signed_bits(value*10+u32(last_digit)));if(value<100000)return format("%d,%.2d%d",value/100,value%100,last_digit);if(value<100000000)return format("%d,%.3d,%.2d%d",(value/100000)%1000,(value/100)%1000,value%100,last_digit);return format("%d,%.3d,%.3d,%.2d%d",(value/100000000)%1000,(value/100000)%1000,(value/100)%1000,value%100,last_digit);}
void GameHud::update_score(){
 if(score.score!=displayed_score){u32 change=u32(wrapping_add(score.score,-displayed_score))>>5;change=std::min(578910u,std::max(1u,change));if(score_increment<i32(change))score_increment=i32(change);const i32 difference=wrapping_add(score.score,-displayed_score);if(difference<score_increment)score_increment=difference;displayed_score=wrapping_add(displayed_score,score_increment);if(score.score<=displayed_score)score_increment=0;}
 if(progress.high_score<displayed_score){progress.high_score_extra=progress.continues;player.mode_flags|=4;progress.high_score=displayed_score;}
}
